WITH b AS (SELECT x FROM TABLE(hcm.system.raw_query('default', 'service-task-v1', '{"size":0,"aggs":{"c":{"composite":{"size":65000,"sources":[{"day":{"date_histogram":{"field":"Data.eventTime","calendar_interval":"day","format":"yyyy-MM-dd"}}},{"code":{"terms":{"field":"Data.boundaryHierarchyCode.district"}}},{"role":{"terms":{"field":"Data.supervisorRole"}}},{"name":{"terms":{"field":"Data.checklistName"}}}]},"aggs":{"qColdChainOk":{"sum":{"field":"Data.qColdChainOk"}},"qVvmOk":{"sum":{"field":"Data.qVvmOk"}},"qOpenVialLabelled":{"sum":{"field":"Data.qOpenVialLabelled"}},"qCorrectSyringe":{"sum":{"field":"Data.qCorrectSyringe"}},"qSafetyBoxUsed":{"sum":{"field":"Data.qSafetyBoxUsed"}},"qAgeScreening":{"sum":{"field":"Data.qAgeScreening"}},"qFingerMarking":{"sum":{"field":"Data.qFingerMarking"}},"qTallyMatchesApp":{"sum":{"field":"Data.qTallyMatchesApp"}},"qTeamComplete":{"sum":{"field":"Data.qTeamComplete"}},"qSocialMobilisation":{"sum":{"field":"Data.qSocialMobilisation"}},"answered":{"sum":{"field":"Data.answeredQuestions"}},"total":{"sum":{"field":"Data.totalQuestions"}}}}}}')) CROSS JOIN UNNEST(CAST(json_extract(result, '$.aggregations.c.buckets') AS array(json))) AS t(x))
SELECT CAST(json_extract_scalar(x, '$.key.day') AS date) AS event_date, d.region, d.district, d.boundary_code,
       json_extract_scalar(x, '$.key.role') AS supervisor_role, json_extract_scalar(x, '$.key.name') AS checklist_name, CAST(json_extract_scalar(x, '$.doc_count') AS bigint) AS submissions,
       CAST(json_extract_scalar(x, '$.answered.value') AS double) AS answered_questions, CAST(json_extract_scalar(x, '$.total.value') AS double) AS total_questions,
       CAST(json_extract_scalar(x, '$.qColdChainOk.value') AS double) AS qcoldchainok, CAST(json_extract_scalar(x, '$.qVvmOk.value') AS double) AS qvvmok, CAST(json_extract_scalar(x, '$.qOpenVialLabelled.value') AS double) AS qopenviallabelled, CAST(json_extract_scalar(x, '$.qCorrectSyringe.value') AS double) AS qcorrectsyringe, CAST(json_extract_scalar(x, '$.qSafetyBoxUsed.value') AS double) AS qsafetyboxused, CAST(json_extract_scalar(x, '$.qAgeScreening.value') AS double) AS qagescreening, CAST(json_extract_scalar(x, '$.qFingerMarking.value') AS double) AS qfingermarking, CAST(json_extract_scalar(x, '$.qTallyMatchesApp.value') AS double) AS qtallymatchesapp, CAST(json_extract_scalar(x, '$.qTeamComplete.value') AS double) AS qteamcomplete, CAST(json_extract_scalar(x, '$.qSocialMobilisation.value') AS double) AS qsocialmobilisation
FROM b JOIN microplan.public.dim_district d ON d.boundary_code = json_extract_scalar(x, '$.key.code')
